#include "mfc_main_dialog.h"
#include "workflow_dialogs.h"
#include <cmath>
namespace {
uint64_t whole(const std::wstring& s,uint64_t maximum){double value=0;if(!uart_number(s,0,static_cast<double>(maximum),value)||value!=std::floor(value))throw std::runtime_error("Note offset/count/index must be whole and within bounds.");return static_cast<uint64_t>(value);}
std::string note_report(const RecordingNotes& n){std::string s="Verified recording: "+message_utf8(n.source.leaf)+"\r\nSHA256: "+n.source.sha256+"\r\nBytes: "+std::to_string(n.source.bytes)+"; notes: "+std::to_string(n.notes.size());for(size_t i=0;i<n.notes.size();++i)s+="\r\n["+std::to_string(i)+"] @"+std::to_string(n.notes[i].offset)+" +"+std::to_string(n.notes[i].count)+" : "+n.notes[i].text;return s;}
}
void CMainDialog::lab_notes_request(const UartLabWindow::Request& r){if(r.fields.size()!=5)return;
    if(r.action==0){const auto path=pick_workflow_file(L"bin",L"Completed recording (*.bin)|*.bin|All files (*.*)|*.*||",true);if(path)lab_.field(r.page,0,path->wstring());return;}
    if(r.action==5){workflow_notes_.reset();lab_.notice(r.page,ui::tr(L"Staged notes cleared; saved notes and source files preserved."));return;}
    if(r.action==2){const auto path=pick_workflow_file(L"sccnotes",L"Private recording notes (*.sccnotes)|*.sccnotes||",true);if(!path)return;start_lab_file(r.page,r.action,[path=*path](const std::atomic<bool>& cancel){auto n=std::make_shared<RecordingNotes>(decode_notes(uart_read_file(path,1024*1024,cancel)));const auto source=path.parent_path()/n->source.leaf;verify_notes(*n,source,cancel);LabFileResult result;result.notes=n;result.source=source;result.report=note_report(*n);return result;});return;}
    const std::filesystem::path source(r.fields[0]);if(source.empty())throw std::runtime_error("Choose a completed recording source first.");
    if(r.action==1){const auto offset=whole(r.fields[1],64ULL*1024*1024*1024),count=whole(r.fields[2],64ULL*1024*1024*1024);const auto text=message_utf8(r.fields[3]);const auto staged=workflow_notes_;start_lab_file(r.page,r.action,[source,staged,offset,count,text](const std::atomic<bool>& cancel){auto n=std::make_shared<RecordingNotes>(staged?*staged:bind_notes(source,cancel));if(staged)verify_notes(*n,source,cancel);n->notes.push_back({offset,count,text});encode_notes(*n);LabFileResult result;result.notes=n;result.source=source;result.report=note_report(*n);return result;});return;}
    if(!workflow_notes_)throw std::runtime_error("Add or load verified notes first.");const auto staged=workflow_notes_;
    if(r.action==3){const auto path=pick_workflow_file(L"sccnotes",L"Private recording notes (*.sccnotes)|*.sccnotes||");if(!path)return;if(std::filesystem::weakly_canonical(path->parent_path())!=std::filesystem::weakly_canonical(source.parent_path()))throw std::runtime_error("Save the notes beside their recording source for portable relative lookup.");const auto bytes=encode_notes(*staged);start_lab_file(r.page,r.action,[source,path=*path,bytes,staged](const std::atomic<bool>& cancel){verify_notes(*staged,source,cancel);uart_write_file(path,bytes,true,cancel);return LabFileResult{"Verified notes saved beside the source. Original recording unchanged.",{}};});return;}
    if(r.action==4){const auto index=whole(r.fields[4],255);if(index>=staged->notes.size())throw std::runtime_error("Note index not staged.");const auto data=replay_.data();if(!data||data->files.size()!=1||data->paths.size()!=1||replay_io_.busy()||replay_load_.busy())throw std::runtime_error("Load this exact single-file recording and wait for replay I/O first.");const auto note=staged->notes[index];replay_.pause(GetTickCount64());start_lab_file(r.page,r.action,[data,staged,note](const std::atomic<bool>& cancel){verify_notes(*staged,data->paths[0],cancel);size_t first=0,last=data->records.size();while(first<last){if(cancel)throw std::runtime_error("Cancelled.");const auto middle=first+(last-first)/2;const auto record=data->records[middle];if(record.offset+record.count<=note.offset)first=middle+1;else last=middle;}if(first>=data->records.size()||data->records[first].offset>note.offset||!data->records[first].count)throw std::runtime_error("Note is at EOF or outside recorded bytes; no seek.");LabFileResult result;result.note_replay=data;result.note_record=first;result.report="Source SHA256 verified. Paused at the record containing the note offset; Play continues from there.";return result;});}
}
